-- Core domain: households, people, receipts, line items, item ownership, settlements.
--
-- Conventions
--   * Primary keys are UUIDs generated by the database (gen_random_uuid() is built in since PG 13).
--   * Money is always BIGINT minor units (cents) in a *_minor column, next to a char(3)
--     ISO 4217 currency code. No REAL / DOUBLE PRECISION / NUMERIC money columns.
--   * Every table has created_at / updated_at (timestamptz); updated_at is maintained by trigger.
--   * Child rows carry household_id and reference parents through composite (household_id, id)
--     foreign keys, so the database itself guarantees that a receipt's payer, an item's owners
--     and a settlement's parties all belong to the same household.
--   * History is preserved: people are archived rather than deleted, receipts are voided rather
--     than deleted, and ownership changes are logged (see V3). Foreign keys to person are
--     NO ACTION, so a person with receipts, owned items or settlements cannot be deleted. They are
--     DEFERRABLE (but immediate by default): deleting a whole household runs
--     SET CONSTRAINTS ALL DEFERRED first, so the cascade through receipts and items finishes before
--     the person rows are checked (see HouseholdRepository.delete).

CREATE FUNCTION set_updated_at() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- household
-- ---------------------------------------------------------------------------
CREATE TABLE household
(
    id               uuid PRIMARY KEY     DEFAULT gen_random_uuid(),
    name             text        NOT NULL CHECK (length(btrim(name)) > 0),
    default_currency char(3)     NOT NULL CHECK (default_currency ~ '^[A-Z]{3}$'),
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER household_set_updated_at
    BEFORE UPDATE ON household
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- person: a member of a household. Not a login account (accounts arrive in M4).
-- ---------------------------------------------------------------------------
CREATE TABLE person
(
    id           uuid PRIMARY KEY     DEFAULT gen_random_uuid(),
    household_id uuid        NOT NULL REFERENCES household (id) ON DELETE CASCADE,
    display_name text        NOT NULL CHECK (length(btrim(display_name)) > 0),
    archived_at  timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT person_household_id_id_key UNIQUE (household_id, id)
);

-- Active members of a household have distinct names (case-insensitive); archived ones may repeat.
CREATE UNIQUE INDEX person_active_name_key
    ON person (household_id, lower(display_name))
    WHERE archived_at IS NULL;

CREATE TRIGGER person_set_updated_at
    BEFORE UPDATE ON person
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- receipt: one shopping trip, paid by one person. The source of truth.
-- ---------------------------------------------------------------------------
CREATE TABLE receipt
(
    id                uuid PRIMARY KEY     DEFAULT gen_random_uuid(),
    household_id      uuid        NOT NULL REFERENCES household (id) ON DELETE CASCADE,
    paid_by_person_id uuid        NOT NULL,
    merchant_name     text,
    purchased_at      timestamptz NOT NULL,
    currency          char(3)     NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    subtotal_minor    bigint,
    tax_minor         bigint,
    total_minor       bigint      NOT NULL,
    status            text        NOT NULL DEFAULT 'draft'
        CHECK (status IN ('draft', 'confirmed', 'void')),
    confirmed_at      timestamptz,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT receipt_household_id_id_key UNIQUE (household_id, id),
    CONSTRAINT receipt_paid_by_fkey FOREIGN KEY (household_id, paid_by_person_id)
        REFERENCES person (household_id, id) ON DELETE NO ACTION DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT receipt_confirmed_at_check CHECK (status <> 'confirmed' OR confirmed_at IS NOT NULL)
);

CREATE INDEX receipt_household_purchased_at_idx ON receipt (household_id, purchased_at DESC);
CREATE INDEX receipt_paid_by_idx ON receipt (household_id, paid_by_person_id);

CREATE TRIGGER receipt_set_updated_at
    BEFORE UPDATE ON receipt
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- receipt_item: one line on a receipt. total_minor may be negative for standalone coupon lines.
-- ---------------------------------------------------------------------------
CREATE TABLE receipt_item
(
    id               uuid PRIMARY KEY        DEFAULT gen_random_uuid(),
    household_id     uuid           NOT NULL,
    receipt_id       uuid           NOT NULL,
    line_number      integer        NOT NULL CHECK (line_number > 0),
    -- The line exactly as read from the receipt (OCR); null for items entered by hand.
    raw_text         text,
    -- The cleaned-up name shown to people.
    description      text           NOT NULL CHECK (length(btrim(description)) > 0),
    -- Quantity is not money; weighed items (e.g. 1.235 lb) need a fractional amount.
    quantity         numeric(12, 3) NOT NULL DEFAULT 1 CHECK (quantity > 0),
    unit_price_minor bigint,
    -- Discount applied to this line, as a positive amount. total_minor is after the discount.
    discount_minor   bigint         NOT NULL DEFAULT 0 CHECK (discount_minor >= 0),
    total_minor      bigint         NOT NULL,
    created_at       timestamptz    NOT NULL DEFAULT now(),
    updated_at       timestamptz    NOT NULL DEFAULT now(),
    CONSTRAINT receipt_item_household_id_id_key UNIQUE (household_id, id),
    CONSTRAINT receipt_item_line_number_key UNIQUE (receipt_id, line_number),
    CONSTRAINT receipt_item_receipt_fkey FOREIGN KEY (household_id, receipt_id)
        REFERENCES receipt (household_id, id) ON DELETE CASCADE
);

CREATE TRIGGER receipt_item_set_updated_at
    BEFORE UPDATE ON receipt_item
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- item_owner: many-to-many receipt_item <-> person.
-- An item may be owned by one, several, or all members of its household. "All" is stored
-- as one row per member at assignment time, so later membership changes never rewrite history.
-- share_weight lets an item be split unevenly (default: equal shares).
-- ---------------------------------------------------------------------------
CREATE TABLE item_owner
(
    household_id    uuid          NOT NULL,
    receipt_item_id uuid          NOT NULL,
    person_id       uuid          NOT NULL,
    share_weight    integer       NOT NULL DEFAULT 1 CHECK (share_weight > 0),
    source          text          NOT NULL DEFAULT 'user' CHECK (source IN ('user', 'model')),
    -- Model confidence for source = 'model'; a probability, not money.
    confidence      numeric(5, 4) CHECK (confidence BETWEEN 0 AND 1),
    created_at      timestamptz   NOT NULL DEFAULT now(),
    updated_at      timestamptz   NOT NULL DEFAULT now(),
    PRIMARY KEY (receipt_item_id, person_id),
    CONSTRAINT item_owner_item_fkey FOREIGN KEY (household_id, receipt_item_id)
        REFERENCES receipt_item (household_id, id) ON DELETE CASCADE,
    CONSTRAINT item_owner_person_fkey FOREIGN KEY (household_id, person_id)
        REFERENCES person (household_id, id) ON DELETE NO ACTION DEFERRABLE INITIALLY IMMEDIATE
);

CREATE INDEX item_owner_person_idx ON item_owner (household_id, person_id);

CREATE TRIGGER item_owner_set_updated_at
    BEFORE UPDATE ON item_owner
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------------
-- settlement: a payment from one member to another that reduces their balance.
-- ---------------------------------------------------------------------------
CREATE TABLE settlement
(
    id             uuid PRIMARY KEY     DEFAULT gen_random_uuid(),
    household_id   uuid        NOT NULL REFERENCES household (id) ON DELETE CASCADE,
    from_person_id uuid        NOT NULL,
    to_person_id   uuid        NOT NULL,
    amount_minor   bigint      NOT NULL CHECK (amount_minor > 0),
    currency       char(3)     NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    settled_at     timestamptz NOT NULL DEFAULT now(),
    note           text,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT settlement_distinct_parties_check CHECK (from_person_id <> to_person_id),
    CONSTRAINT settlement_from_fkey FOREIGN KEY (household_id, from_person_id)
        REFERENCES person (household_id, id) ON DELETE NO ACTION DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT settlement_to_fkey FOREIGN KEY (household_id, to_person_id)
        REFERENCES person (household_id, id) ON DELETE NO ACTION DEFERRABLE INITIALLY IMMEDIATE
);

CREATE INDEX settlement_household_settled_at_idx ON settlement (household_id, settled_at DESC);
CREATE INDEX settlement_from_idx ON settlement (household_id, from_person_id);
CREATE INDEX settlement_to_idx ON settlement (household_id, to_person_id);

CREATE TRIGGER settlement_set_updated_at
    BEFORE UPDATE ON settlement
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();